write {"content": "#!/usr/bin/env bun
// pv-reload — CDP-reload the pine IDE page so a fixture swap takes effect.
const list = await (await fetch("http://127.0.0.1:9222/json/list")).json();
const page = list.find((t) => t.type === "page" && t.url.includes(":9851/pine.html"));
if (!page) { console.error("NO_PAGE"); process.exit(1); }
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((ok, no) => { ws.onopen = ok; ws.onerror = no; });
ws.send(JSON.stringify({ id: 1, method: "Page.reload", params: { ignoreCache: true } }));
await new Promise((r) => setTimeout(r, 1500));
ws.close();
console.log("reloaded");
